class PalindromeMaker:
    def __init__(self, string: str):
        self.string = string

    def is_palindrome(self, s: str) -> bool:
        """ Test if given string is a palindrome """
        left, right = 0, len(s) - 1
        while left < right:
            if s[left] != s[right]:
                return False
            left += 1
            right -= 1
        return True

    def make_palindrome(self) -> str:
        """ Find the shortest palindrome that begins with a supplied string """
        if not self.string:
            return ''

        for i in range(len(self.string), 0, -1):
            prefix = self.string[:i]
            suffix = self.string[i:]
            if self.is_palindrome(suffix):
                return self.string + prefix[::-1]
        return self.string

    def reverse_prefix(self, prefix: str) -> str:
        """ Reverse a prefix of the string """
        return prefix[::-1]

