    if not isinstance(a, int) or not isinstance(b, int):
        raise TypeError("Both inputs must be integers.")

    # Handle zero input
    if a == 0 and b == 0:
        return 0
    elif a == 0:
        return abs(b)
    elif b == 0:
        return abs(a)

    # Handle negative inputs
    a = abs(a)
