import math

class Polynomial:
    def __init__(self, coefficients):
        if len(coefficients) % 2 != 0:
            raise ValueError("Polynomial must have an even number of coefficients")
        self.coefficients = coefficients

    def evaluate(self, x):
        """Evaluates the polynomial at point x"""
        return sum(coeff * math.pow(x, i) for i, coeff in enumerate(self.coefficients))

    def find_zero(self):
        """Finds a zero of the polynomial"""
        # Using the Rational Root Theorem to narrow down possible roots
        factors = [p for p in self.coefficients if p != 0]
        for p in factors:
            q = self.coefficients[-1] // p
            if q == 0:
                continue
            x = -p / q
            if self.evaluate(x) == 0:
                return x
        # If no rational root is found, use numerical method (e.g. Newton-Raphson)
