            raise ValueError("Polynomial coefficients must have an even number of terms")
        self.coefficients = coefficients

    def evaluate(self, x):
        return np.polyval(self.coefficients, x)

    def find_zero(self):
        # Newton's method for finding roots
        x = self.coefficients[-1] / self.coefficients[-2]
        while abs(self.evaluate(x)) > 1e-6:
            x = x - self.evaluate(x) / self.derivative(x)
        return x

    def derivative(self, x):
        # Compute derivative of the polynomial at point x
        return np.polyder(self.coefficients)(x)

def poly(xs: list, x: float):
