class Palindrome:
    def __init__(self, string: str):
        self.string = string

    def _is_palindrome(self, s: str) -> bool:
        """Check if a given string is a palindrome."""
        return s == s[::-1]

    def make_palindrome(self) -> str:
        """Find the shortest palindrome that begins with the supplied string."""
        if not self.string:
            return ''

        i = len(self.string)
        while i > 0:
            postfix = self.string[-i:]
            if self._is_palindrome(postfix):
                prefix = self.string[:-i]
                return self.string + prefix[::-1]
            i -= 1

        # If no palindrome postfix found, return the original string
        return self.string


